package com.gestordevendas.api.food;
import com.gestordevendas.api.company.Company; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="beverages") public class Beverage { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @Column(nullable=false) private String name; @Column(nullable=false) private BigDecimal price; @Column(nullable=false) private BigDecimal cost; protected Beverage(){} public static Beverage create(Company c,String n,BigDecimal p,BigDecimal cost){var x=new Beverage();x.id=UUID.randomUUID();x.company=c;x.update(n,p,cost);return x;} public void update(String n,BigDecimal p,BigDecimal c){name=n;price=p;cost=c==null?BigDecimal.ZERO:c;} public UUID getId(){return id;} public String getName(){return name;} public BigDecimal getPrice(){return price;} public BigDecimal getCost(){return cost;} }